-- Recorte mínimo do schema cockpit para o laboratório da coleta por perfil.
create schema if not exists cockpit;
create table cockpit.clientes (customer text primary key);
create table cockpit.monitcad_scripts (customer text, tipo text, sql text, dialeto text, sufixo text, updated_by text, updated_at timestamptz default now(), primary key (customer,tipo));
create table cockpit.monitmov_cenarios (id bigserial primary key, customer text, analise text, dim1 text default '*', dim2 text default '*', dim3 text default '*', dim4 text default '*', descricao text, esperado boolean default true, etapa text, responsavel text, updated_by text, updated_at timestamptz default now());
create table cockpit.monitmov_medicoes (id bigserial primary key, customer text, ambiente text default 'producao', data_medicao date, semana integer, hora_medicao text, periodo_ini date, periodo_fim date, origem text default 'upload', payload jsonb, created_at timestamptz default now());
create table cockpit.monitmov_dimensoes (id bigserial primary key, medicao_id bigint, customer text, ambiente text default 'producao', data_medicao date, analise text, descricao text, dim1_nome text, dim1 text, dim2_nome text, dim2 text, dim3_nome text, dim3 text, dim4_nome text, dim4 text, periodo text, qtde numeric default 0, qtd_doc numeric);
create table cockpit.monitmov_itens (id bigserial primary key, medicao_id bigint, customer text, ambiente text default 'producao', data_medicao date, tabela text, descricao text, modulo text, filtro text, quantidade numeric default 0, valor numeric, periodo text, observacao text);
create table cockpit.protheus_ambientes (customer text, ambiente text, url_rest text, environment text, empresa text default '01', filial text default '01', usuario text, senha_enc text, token_enc text, banco text, sufixo text, timeout_s integer default 120, limite_linhas integer default 50000, ativo boolean default true, ultimo_teste_em timestamptz, ultimo_teste_ok boolean, ultimo_teste_msg text, observacao text, updated_by text, updated_at timestamptz default now(), created_at timestamptz default now(), ssl_verificar boolean default true, integ_desde date, integ_grupos text[], primary key (customer, ambiente));
create table cockpit.protheus_coletas (id bigserial primary key, customer text, ambiente text, tipo text, iniciado_em timestamptz default now(), duracao_ms integer, ok boolean default false, http_status integer, linhas integer, medicoes integer, itens integer, bytes integer, data_medicao date, erro text, disparado_por text);
